/// @brief Forwards the messages of this interface to a Handler.
class Receiver {
public:
    /// @brief Forwards to @p handler, which must outlive the receiver.
    explicit Receiver(Handler& handler) noexcept : handler_(&handler) {}

    /**
     * @brief Registers this receiver with @p dispatcher (before `dispatcher.start()`).
     * @return The first registration error, or wireforge::Status::Ok.
     */
    [[nodiscard]] wireforge::Status attach(Dispatcher& dispatcher) noexcept {
        return wireforge::first_error(
            dispatcher.add(kVersionQueryId, wireforge::MessageHandler::bind<&Receiver::receiveVersionQuery>(*this)),
            dispatcher.add(kVersionReplyId, wireforge::MessageHandler::bind<&Receiver::receiveVersionReply>(*this)),
            dispatcher.add(kJobStartId, wireforge::MessageHandler::bind<&Receiver::receiveJobStart>(*this)),
            dispatcher.add(kPhaseStartId, wireforge::MessageHandler::bind<&Receiver::receivePhaseStart>(*this)),
            dispatcher.add(kPhaseDoneId, wireforge::MessageHandler::bind<&Receiver::receivePhaseDone>(*this)),
            dispatcher.add(kProgressId, wireforge::MessageHandler::bind<&Receiver::receiveProgress>(*this)),
            dispatcher.add(kHeartbeatId, wireforge::MessageHandler::bind<&Receiver::receiveHeartbeat>(*this)),
            dispatcher.add(kHeartbeatAckId, wireforge::MessageHandler::bind<&Receiver::receiveHeartbeatAck>(*this)),
            dispatcher.add(kResultSummaryId, wireforge::MessageHandler::bind<&Receiver::receiveResultSummary>(*this)),
            dispatcher.add(kShutdownId, wireforge::MessageHandler::bind<&Receiver::receiveShutdown>(*this)),
            dispatcher.set_fallback(wireforge::FallbackHandler::bind<&Receiver::receiveUnknown>(*this)));
    }

private:
    wireforge::Status receiveVersionQuery(const wireforge::RawMessage& raw) noexcept {
        return handler_->onVersionQueryRaw(raw);
    }

    wireforge::Status receiveVersionReply(const wireforge::RawMessage& raw) noexcept {
        handler_->onUnhandled(wireforge::UnhandledFrame{
            wireforge::UnhandledReason::NotForThisNode,
            wireforge::Status::NotForThisNode, kVersionReplyId, raw.frame});
        return wireforge::Status::NotForThisNode;
    }

    wireforge::Status receiveJobStart(const wireforge::RawMessage& raw) noexcept {
        return handler_->onJobStartRaw(raw);
    }

    wireforge::Status receivePhaseStart(const wireforge::RawMessage& raw) noexcept {
        return handler_->onPhaseStartRaw(raw);
    }

    wireforge::Status receivePhaseDone(const wireforge::RawMessage& raw) noexcept {
        handler_->onUnhandled(wireforge::UnhandledFrame{
            wireforge::UnhandledReason::NotForThisNode,
            wireforge::Status::NotForThisNode, kPhaseDoneId, raw.frame});
        return wireforge::Status::NotForThisNode;
    }

    wireforge::Status receiveProgress(const wireforge::RawMessage& raw) noexcept {
        handler_->onUnhandled(wireforge::UnhandledFrame{
            wireforge::UnhandledReason::NotForThisNode,
            wireforge::Status::NotForThisNode, kProgressId, raw.frame});
        return wireforge::Status::NotForThisNode;
    }

    wireforge::Status receiveHeartbeat(const wireforge::RawMessage& raw) noexcept {
        return handler_->onHeartbeatRaw(raw);
    }

    wireforge::Status receiveHeartbeatAck(const wireforge::RawMessage& raw) noexcept {
        handler_->onUnhandled(wireforge::UnhandledFrame{
            wireforge::UnhandledReason::NotForThisNode,
            wireforge::Status::NotForThisNode, kHeartbeatAckId, raw.frame});
        return wireforge::Status::NotForThisNode;
    }

    wireforge::Status receiveResultSummary(const wireforge::RawMessage& raw) noexcept {
        handler_->onUnhandled(wireforge::UnhandledFrame{
            wireforge::UnhandledReason::NotForThisNode,
            wireforge::Status::NotForThisNode, kResultSummaryId, raw.frame});
        return wireforge::Status::NotForThisNode;
    }

    wireforge::Status receiveShutdown(const wireforge::RawMessage& raw) noexcept {
        return handler_->onShutdownRaw(raw);
    }

    wireforge::Status receiveUnknown(std::uint64_t message_id,
                                 const wireforge::RawMessage& raw) noexcept {
        handler_->onUnhandled(wireforge::UnhandledFrame{
            wireforge::UnhandledReason::UnknownMessageId,
            wireforge::Status::UnknownMessageId, message_id, raw.frame});
        return wireforge::Status::UnknownMessageId;
    }

    Handler* handler_;
};

/**
 * @brief Receive side of this interface: frame decoder, dispatcher and receiver.
 *
 * Construct it, check status(), then pass decoder() and dispatcher() to a Link.
 */
class Endpoint {
public:
    /// @brief Wires a receiver for @p handler and starts the dispatcher.
    explicit Endpoint(Handler& handler) noexcept
        : receiver_(handler),
          status_(wire(receiver_, dispatcher_)) {}

    /// @brief Result of the registration; must be Ok before use.
    [[nodiscard]] wireforge::Status status() const noexcept { return status_; }
    /// @brief Frame decoder for the Link.
    [[nodiscard]] Decoder& decoder() noexcept { return decoder_; }
    /// @brief Dispatcher for the Link.
    [[nodiscard]] const Dispatcher& dispatcher() const noexcept {
        return dispatcher_;
    }
    /// @brief Encodes a VersionReply frame and sends it on @p link.
    template <typename L>
    [[nodiscard]] static wireforge::Status send(L& link, const VersionReply& message,
        const Header& header = Header{}) noexcept {
        return link.send([&message, &header](wireforge::Span<std::uint8_t> buffer, std::size_t& size) noexcept {
            return encode_frame(message, buffer, size, header);
        });
    }

    /// @brief Encodes a PhaseDone frame and sends it on @p link.
    template <typename L>
    [[nodiscard]] static wireforge::Status send(L& link, const PhaseDone& message,
        const Header& header = Header{}) noexcept {
        return link.send([&message, &header](wireforge::Span<std::uint8_t> buffer, std::size_t& size) noexcept {
            return encode_frame(message, buffer, size, header);
        });
    }

    /// @brief Encodes a Progress frame and sends it on @p link.
    template <typename L>
    [[nodiscard]] static wireforge::Status send(L& link, const Progress& message,
        const Header& header = Header{}) noexcept {
        return link.send([&message, &header](wireforge::Span<std::uint8_t> buffer, std::size_t& size) noexcept {
            return encode_frame(message, buffer, size, header);
        });
    }

    /// @brief Encodes a HeartbeatAck frame and sends it on @p link.
    template <typename L>
    [[nodiscard]] static wireforge::Status send(L& link, const HeartbeatAck& message,
        const Header& header = Header{}) noexcept {
        return link.send([&message, &header](wireforge::Span<std::uint8_t> buffer, std::size_t& size) noexcept {
            return encode_frame(message, buffer, size, header);
        });
    }

    /// @brief Encodes a ResultSummary frame and sends it on @p link.
    template <typename L>
    [[nodiscard]] static wireforge::Status send(L& link, const ResultSummary& message,
        const Header& header = Header{}) noexcept {
        return link.send([&message, &header](wireforge::Span<std::uint8_t> buffer, std::size_t& size) noexcept {
            return encode_frame(message, buffer, size, header);
        });
    }


private:
    static wireforge::Status wire(Receiver& receiver, Dispatcher& dispatcher) noexcept {
        const wireforge::Status attached = receiver.attach(dispatcher);
        return wireforge::first_error(attached, dispatcher.start());
    }

    Decoder decoder_{};
    Dispatcher dispatcher_{kHeaderLayout};
    Receiver receiver_;
    wireforge::Status status_;
};

